import assert from 'node:assert/strict';import {join} from 'node:path';import {pathToFileURL} from 'node:url';import * as reference from './reference.mjs';import {readFileSync} from 'node:fs';import {createHash} from 'node:crypto';
const original=readFileSync(new URL('../core-prerequisites/original-fiber.mjs',import.meta.url),'utf8'),provenance=JSON.parse(readFileSync(new URL('./provenance.json',import.meta.url),'utf8'));assert.equal(createHash('sha256').update(original).digest('hex'),provenance.original_program_emit_sha256);const referenceText=readFileSync(new URL('./reference.mjs',import.meta.url),'utf8'),start=original.indexOf('        task?.catch('),end=original.indexOf('.catch((error) => this.ctx.logger.error(error));',start)+'.catch((error) => this.ctx.logger.error(error));'.length;assert.ok(referenceText.includes(original.slice(start,end).trim()));assert.ok(original.includes('return instance?.[symbols.init]?.();'));assert.ok(referenceText.includes('return instance?.[initKey]?.();'));
const dir=process.argv[2];let groups=0;
async function run(m){const results=[],check=async(n,f)=>{await f();results.push(n);};
 await check('nullish base skips entire chain',()=>{for(const b of [null,undefined])assert.equal(m.chain(b,()=>{throw 1;},()=>{throw 2;},()=>{throw 3;}),undefined);});
 await check('nullish method skips args and tail',()=>{for(const v of [null,undefined])assert.equal(m.chain({method:v},()=> 'method',()=>{throw 1;},()=>{throw 2;}),undefined);});
 await check('property receiver and ordered continuation',()=>{const trace=[],base={get method(){trace.push('get');return function(arg){assert.equal(this,base);trace.push(['call',arg]);return {get tail(){trace.push('tail-get');return 9;}};}}};assert.equal(m.chain(base,()=>{trace.push('key');return 'method';},()=>{trace.push('arg');return 7;},()=>{trace.push('tail-key');return 'tail';}),9);assert.deepEqual(trace,['key','get','arg',['call',7],'tail-key','tail-get']);});
 await check('noncallable values evaluate args then throw',()=>{for(const bad of [false,0,'',{},Symbol('x')]){let count=0;assert.throws(()=>m.method({f:bad},()=> 'f',()=>++count),e=>e instanceof TypeError);assert.equal(count,1);}});
 await check('receiver optional versus callee optional',()=>{assert.equal(m.receiver(null,()=>{throw 1;},()=>{throw 2;}),undefined);let count=0;assert.throws(()=>m.receiver({f:null},()=> 'f',()=>++count),e=>e instanceof TypeError);assert.equal(count,1);assert.throws(()=>m.method(null,()=> 'f',()=>1),e=>e instanceof TypeError);});
 await check('grouping terminates chain short circuit',()=>{assert.throws(()=>m.grouped(null,()=>{throw 1;},()=>{throw 2;}),e=>e instanceof TypeError);assert.throws(()=>m.chain({f:()=>null},()=> 'f',()=>1,()=> 'tail'),e=>e instanceof TypeError);});
 await check('root value call remains unbound',()=>{assert.equal(m.valueCall(function(){return this;},()=>1),undefined);assert.equal(m.valueCall(null,()=>{throw 1;}),undefined);});
 await check('spread order and native receiver',()=>{const log=[],o={f(...args){assert.equal(this,o);log.push(args);return args;}};assert.deepEqual(m.spread(o,()=>{log.push('key');return 'f';},()=>{log.push('arg');return 1;},()=>{log.push('iter');return [2,3];}),[1,2,3]);assert.deepEqual(log,['key','arg','iter',[1,2,3]]);});
 await check('abrupt key getter arg iterator identity',()=>{const err={sentinel:1};assert.throws(()=>m.method({},()=>{throw err;},()=>1),e=>e===err);assert.throws(()=>m.method({get f(){throw err;}},()=> 'f',()=>1),e=>e===err);assert.throws(()=>m.method({f(){}},()=> 'f',()=>{throw err;}),e=>e===err);assert.throws(()=>m.spread({f(){}},()=> 'f',()=>1,()=>({[Symbol.iterator](){throw err;}})),e=>e===err);});
 await check('proxy native method apply receiver',()=>{let receiver;const o={f:new Proxy(function(){},{apply(_target,self,args){receiver=self;return args;}})};assert.deepEqual(m.method(o,()=> 'f',()=>9),[9]);assert.equal(receiver,o);});
 await check('await optional skip and own continuation',async()=>{assert.equal(await m.awaitKey(null,()=>{throw 1;},()=>{throw 2;}),undefined);const o={f(a){assert.equal(this,o);return a;}};assert.equal(await m.awaitKey(o,()=>Promise.resolve('f'),()=>Promise.resolve(8)),8);const e={async:1};await assert.rejects(m.awaitKey(o,()=>Promise.reject(e),()=>1),x=>x===e);});
 await check('yield short circuit and receiver',()=>{assert.deepEqual(m.yieldKey(null).next(),{value:undefined,done:true});const o={f(a){assert.equal(this,o);return a;}};const g=m.yieldKey(o);assert.deepEqual(g.next(),{value:'key',done:false});assert.deepEqual(g.next('f'),{value:'arg',done:false});assert.deepEqual(g.next(6),{value:6,done:true});});
 await check('adjacent call returned value has no receiver',()=>{const o={get(){assert.equal(this,o);return function(v){assert.equal(this,undefined);return v;};}};assert.equal(m.returnedCall(o),1);assert.equal(m.returnedCall({get(){return null;}}),undefined);assert.throws(()=>m.returnedCall({get(){return false;}}),e=>e instanceof TypeError);});
 await check('yield captures method receiver before suspension',()=>{let gets=0;const o={get f(){gets++;return function(v){assert.equal(this,o);return v;};}},g=m.yieldKey(o);g.next();assert.deepEqual(g.next('f'),{value:'arg',done:false});assert.equal(gets,1);Object.defineProperty(o,'f',{value:()=>99});assert.deepEqual(g.next(7),{value:7,done:true});});
 await check('await retains method across argument suspension',async()=>{let release,entered;const wait=new Promise(r=>release=r),signal=new Promise(r=>entered=r),o={f(v){assert.equal(this,o);return v;}};const pending=m.awaitKey(o,()=> 'f',()=>{entered();return wait;});await signal;o.f=()=>99;release(5);assert.equal(await pending,5);});
 await check('original Fiber init receiver and nullish',()=>{const s=Symbol('init'),o={[s](){assert.equal(this,o);return 'initialized';}};assert.equal(m.initialize(o,s),'initialized');assert.equal(m.initialize(null,s),undefined);assert.equal(m.initialize({},s),undefined);assert.throws(()=>m.initialize({[s]:false},s),e=>e instanceof TypeError);});
 await check('original task continuous short circuit',()=>{const ctx={ctx:{logger:{error(){throw 1;}}}};assert.equal(m.taskCleanup.call(ctx,undefined,{epoch:true},()=>{throw 2;},()=>{throw 3;}),undefined);});
 await check('original task cleanup active/inactive branch',async()=>{for(const epoch of [true,false]){const log=[],runner={epoch},ctx={ctx:{logger:{error:e=>log.push(['error',e])}}},dispose=()=>{log.push('dispose');};await m.taskCleanup.call(ctx,Promise.reject('cause'),runner,dispose,fn=>{assert.equal(fn,dispose);log.push('finalize');});assert.deepEqual(log,epoch?['finalize']:['dispose']);}});
 await check('original task rejection logger identity',async()=>{const e={cleanup:1},logged=[],ctx={ctx:{logger:{error(x){logged.push(x);return 'logged';}}}};assert.equal(await m.taskCleanup.call(ctx,Promise.reject('cause'),{epoch:false},()=>{throw e;},()=>{}),'logged');assert.equal(logged[0],e);});
 return results;}
for(const target of ['js','js-browser'])for(const profile of ['factory','native-esm']){
 const m=profile==='factory'?(await import(pathToFileURL(join(dir,target+'.mjs')))).instantiateMithrilNative({}):await import(pathToFileURL(join(dir,target+'-esm','index.mjs')));
 const actual=await run(m),expected=await run(reference);assert.deepEqual(actual,expected);groups+=actual.length;console.log(`Native optional chains actual ${target} ${profile} CLI: ${actual.length} paired groups; receiver/nullish/full-chain/grouping/own await-yield and original Fiber expressions.`);
}
assert.equal(groups,76);console.log('Native optional chains:76 paired groups; source expressions only, not full core lifecycle/browser/native/Q9.');
